function cp_num(array $v, string $key, float $fallback = 0): float { return is_numeric($v[$key] ?? null) ? (float)$v[$key] : $fallback; }
function cp_distance(float $aLat,float $aLng,float $bLat,float $bLng):float{$r=6371;$dLat=deg2rad($bLat-$aLat);$dLng=deg2rad($bLng-$aLng);$x=sin($dLat/2)**2+cos(deg2rad($aLat))*cos(deg2rad($bLat))*sin($dLng/2)**2;return $r*2*atan2(sqrt($x),sqrt(max(0,1-$x)));}
function cp_bearing(float $aLat,float $aLng,float $bLat,float $bLng):float{$y=sin(deg2rad($bLng-$aLng))*cos(deg2rad($bLat));$x=cos(deg2rad($aLat))*sin(deg2rad($bLat))-sin(deg2rad($aLat))*cos(deg2rad($bLat))*cos(deg2rad($bLng-$aLng));return fmod(rad2deg(atan2($y,$x))+360,360);}
function cp_angle(float $a,float $b):float{$v=abs($a-$b);return min($v,360-$v);}
