 $result=[];$picked=[];$current=$pending[0]??null;while($pending){$allowed=array_values(array_filter($pending,static fn($s)=>$s['type']==='pickup'||isset($picked[$s['passengerBookingId']])));if(!$allowed)$allowed=$pending;$best=null;$bestD=INF;foreach($allowed as $s){$d=$current?cp_distance((float)$current['lat'],(float)$current['lng'],(float)$s['lat'],(float)$s['lng']):0;if($d<$bestD){$best=$s;$bestD=$d;}}$best['order']=count($result)+1;$result[]=$best;if($best['type']==='pickup')$picked[$best['passengerBookingId']]=true;$pending=array_values(array_filter($pending,static fn($s)=>$s['stopId']!==$best['stopId']));$current=$best;}
